1	import { db } from "../lib/db";
2	import { registrarConfigured, renewDomain } from "../lib/registrar";
3	import { vpsTerm, vpsTermPriceCents, domainTerm, domainTermPriceCents, addMonths } from "../lib/billing-terms";
4	import { DEDICATED_IP_PRICE_CENTS } from "../lib/dedicated-ip";
5	
6	const GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
7	const RENEW_DAYS = 30;
8	const DOMAIN_RENEW_WINDOW_DAYS = 7;
9	/** Days a server stays SUSPENDED (unpaid) before it is permanently terminated. */
10	const TERMINATE_DAYS = Number(process.env.NXEON_TERMINATE_DAYS ?? 10);
11	/** Warn the customer this many days before termination. */
12	const WARN_BEFORE_TERMINATE_DAYS = Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS ?? 2);
13	const DAY = 86400_000;
14	
15	/**
16	 * Subscription sweep, run periodically by the worker:
17	 *  - expired + autoRenew + sufficient balance  -> charge wallet, extend 30 days
18	 *  - expired beyond grace (or autoRenew off)   -> queue SUSPEND with unpaid note
19	 * Free servers (isFree) are never touched.
20	 */
21	export async function billingSweep() {
22	  const now = new Date();
23	
24	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
25	  const soon = new Date(now.getTime() + 3 * 86400_000);
26	  const upcoming = await db.server.findMany({
27	    where: {
28	      isFree: false,
29	      expiresAt: { gt: now, lt: soon },
30	      status: { in: ["RUNNING", "STOPPED"] },
31	    },
32	    include: { plan: true, user: true, gamePlan: true },
33	  });
34	  for (const server of upcoming) {
35	    const warnCents = server.gamePlan ? server.gamePlan.priceCents : vpsTermPriceCents(server.plan.priceCents, server.termMonths);
36	    if (server.autoRenew && server.user.balanceCents >= warnCents) continue;
37	    const already = await db.notification.findFirst({
38	      where: {
39	        userId: server.userId,
40	        title: { contains: server.hostname },
41	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
42	        AND: { title: { contains: "renews soon" } },
43	      },
44	    });
45	    if (!already) {
46	      await db.notification.create({
47	        data: {
48	          userId: server.userId,
49	          title: `${server.hostname} renews soon — action needed`,
50	          body: server.autoRenew
51	            ? `Renewal is $${(server.plan.priceCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
52	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
53	          href: `/dashboard/servers/${server.id}`,
54	        },
55	      });
56	    }
57	  }
58	  const due = await db.server.findMany({
59	    where: {
60	      isFree: false,
61	      expiresAt: { lt: now },
62	      status: { in: ["RUNNING", "STOPPED"] },
63	    },
64	    include: { plan: true, user: true, gamePlan: true },
65	  });
66	
67	  for (const server of due) {
68	    const graceEnd = new Date(server.expiresAt!.getTime() + GRACE_DAYS * 86400_000);
69	    const renewTerm = vpsTerm(server.termMonths);
70	    const isGame = !!server.gamePlan;
71	    const renewMonths = isGame ? server.gamePlan!.termMonths : renewTerm.months;
72	    const renewCents = isGame
73	      ? server.gamePlan!.priceCents
74	      : vpsTermPriceCents(server.plan.priceCents, renewTerm.months) +
75	        (server.wantsDedicatedIp ? DEDICATED_IP_PRICE_CENTS * renewTerm.months : 0);
76	
77	    if (server.autoRenew && server.user.balanceCents >= renewCents) {
78	      const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
79	      const newExpiry = addMonths(base, renewMonths);
80	      await db.$transaction([
81	        db.user.update({
82	          where: { id: server.userId },
83	          data: { balanceCents: { decrement: renewCents } },
84	        }),
85	        db.walletTransaction.create({
86	          data: {
87	            userId: server.userId,
88	            amountCents: -renewCents,
89	            description: `Renewal: ${isGame ? server.gamePlan!.name : `${server.plan.name} VPS`} (${server.hostname})`,
90	          },
91	        }),
92	        db.server.update({
93	          where: { id: server.id },
94	          data: { expiresAt: newExpiry },
95	        }),
96	        db.auditLog.create({
97	          data: { userId: server.userId, action: "billing.renewed", detail: server.id },
98	        }),
99	      ]);
100	      console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
101	    } else if (now > graceEnd) {
102	      const pending = await db.job.count({
103	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
104	      });
105	      if (pending === 0) {
106	        await db.server.update({
107	          where: { id: server.id },
108	          data: { suspendedNote: "unpaid — renew from your billing page to restore access" },
109	        });
110	        await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
111	        await db.auditLog.create({
112	          data: { userId: server.userId, action: "billing.suspended_unpaid", detail: server.id },
113	        });
114	        await db.notification.create({
115	          data: {
116	            userId: server.userId,
117	            title: `${server.hostname} suspended — payment overdue`,
118	            body: "Pay from the server page to restore access instantly.",
119	            href: `/dashboard/servers/${server.id}`,
120	          },
121	        });
122	        console.log(`[billing] suspending unpaid ${server.hostname}`);
123	      }
124	    }
125	  }
126	
127	  await terminateOverdue(now);
128	
129	  await domainAutoRenewSweep(now);
130	}
131	
132	/**
133	 * Terminate servers that have been SUSPENDED (unpaid) past the termination window,
134	 * reclaiming disk + dedicated IP. Warns the customer before the final deletion.
135	 * A payment before this point unsuspends the server, so this only ever hits
136	 * genuinely abandoned accounts. Free servers are never terminated.
137	 */
138	async function terminateOverdue(now: Date) {
139	  const suspended = await db.server.findMany({
140	    where: { isFree: false, status: "SUSPENDED", expiresAt: { not: null } },
141	  });
142	  for (const server of suspended) {
143	    const terminateAt = server.expiresAt!.getTime() + (GRACE_DAYS + TERMINATE_DAYS) * DAY;
144	    const warnAt = terminateAt - WARN_BEFORE_TERMINATE_DAYS * DAY;
145	
146	    if (now.getTime() >= terminateAt) {
147	      const pending = await db.job.count({
148	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
149	      });
150	      if (pending > 0) continue;
151	      await db.server.update({ where: { id: server.id }, data: { status: "DELETING" } });
152	      await db.job.create({ data: { type: "DELETE", serverId: server.id } });
153	      await db.auditLog.create({
154	        data: { userId: server.userId, action: "billing.terminated_unpaid", detail: server.id },
155	      });
156	      await db.notification.create({
157	        data: {
158	          userId: server.userId,
159	          title: `${server.hostname} was permanently deleted`,
160	          body: "Your server and its data were removed after prolonged non-payment.",
161	        },
162	      });
163	      console.log(`[billing] terminating abandoned ${server.hostname}`);
164	    } else if (now.getTime() >= warnAt) {
165	      const already = await db.notification.findFirst({
166	        where: {
167	          userId: server.userId,
168	          title: { contains: server.hostname },
169	          AND: { title: { contains: "will be deleted" } },
170	          createdAt: { gt: new Date(now.getTime() - 2 * DAY) },
171	        },
172	      });
173	      if (!already) {
174	        await db.notification.create({
175	          data: {
176	            userId: server.userId,
177	            title: `${server.hostname} will be deleted soon`,
178	            body: `This suspended server and all its data will be permanently deleted on ${new Date(terminateAt).toISOString().slice(0, 10)} unless you pay. Restore it now from your billing page.`,
179	            href: `/dashboard/servers/${server.id}`,
180	          },
181	        });
182	      }
183	    }
184	  }
185	}
186	
187	/**
188	 * Auto-renew domains expiring within 7 days when the owner opted in and has
189	 * the funds. Charges the wallet, extends expiry +365d and notifies the owner.
190	 * Failures (registrar error, misconfig) notify the owner to renew manually and
191	 * never charge the wallet.
192	 */
193	async function domainAutoRenewSweep(now: Date) {
194	  if (!registrarConfigured()) return; // registrar not configured — skip silently
195	
196	  const cutoff = new Date(now.getTime() + DOMAIN_RENEW_WINDOW_DAYS * 86400_000);
197	  const domains = await db.domain.findMany({
198	    where: {
199	      autoRenew: true,
200	      status: "ACTIVE",
201	      expiresAt: { not: null, lt: cutoff },
202	    },
203	    include: { user: true },
204	  });
205	
206	  for (const domain of domains) {
207	    if (!domain.expiresAt) continue;
208	    const dTerm = domainTerm(domain.termYears);
209	    const dRenewCents = domainTermPriceCents(domain.priceCents, dTerm.years); // retail (customer)
210	    const dRegistrarCost = (domain.costCents || domain.priceCents) * dTerm.years; // cost (registrar)
211	    if (domain.user.balanceCents < dRenewCents) {
212	      const already = await db.notification.findFirst({
213	        where: {
214	          userId: domain.userId,
215	          title: { contains: domain.name },
216	          AND: { title: { contains: "auto-renew failed" } },
217	          createdAt: { gt: new Date(now.getTime() - 3 * 86400_000) },
218	        },
219	      });
220	      if (!already) {
221	        await db.notification.create({
222	          data: {
223	            userId: domain.userId,
224	            title: `${domain.name} auto-renew failed — top up to renew`,
225	            body: `Renewal is $${(dRenewCents / 100).toFixed(2)} (${dTerm.label}) but your balance is $${(domain.user.balanceCents / 100).toFixed(2)}. Top up and renew manually before ${domain.expiresAt.toISOString().slice(0, 10)}.`,
226	            href: `/dashboard/domains`,
227	          },
228	        });
229	      }
230	      continue;
231	    }
232	
233	    try {
234	      await renewDomain(domain.name, dTerm.years, dRegistrarCost);
235	    } catch (e) {
236	      console.error(`[billing] domain auto-renew failed for ${domain.name}`, e);
237	      await db.notification.create({
238	        data: {
239	          userId: domain.userId,
240	          title: `${domain.name} auto-renew failed — please renew manually`,
241	          body: `We couldn't renew ${domain.name} automatically: ${String((e as any)?.message ?? e).slice(0, 200)}. Renew it manually from your domains page.`,
242	          href: `/dashboard/domains`,
243	        },
244	      });
245	      continue;
246	    }
247	
248	    const newExpiry = new Date(domain.expiresAt.getTime() + dTerm.years * 365 * 86400_000);
249	    await db.$transaction([
250	      db.user.update({
251	        where: { id: domain.userId },
252	        data: { balanceCents: { decrement: dRenewCents } },
253	      }),
254	      db.walletTransaction.create({
255	        data: {
256	          userId: domain.userId,
257	          amountCents: -dRenewCents,
258	          description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
259	        },
260	      }),
261	      db.domain.update({ where: { id: domain.id }, data: { expiresAt: newExpiry } }),
262	      db.auditLog.create({
263	        data: { userId: domain.userId, action: "domain.auto_renewed", detail: domain.name },
264	      }),
265	    ]);
266	    await db.notification.create({
267	      data: {
268	        userId: domain.userId,
269	        title: `${domain.name} renewed automatically`,
270	        body: `Charged $${(domain.priceCents / 100).toFixed(2)}. New expiry: ${newExpiry.toISOString().slice(0, 10)}.`,
271	        href: `/dashboard/domains`,
272	      },
273	    });
274	    console.log(`[billing] auto-renewed domain ${domain.name} until ${newExpiry.toISOString()}`);
275	  }
276	}
