55	/**
56	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
57	 * plus any control-panel/app install script and selected add-ons. Long installs
58	 * run in the background so the VM reports ready promptly.
59	 */
60	function buildCloudInit(server: any): string {
61	  const addons = (server.addons ?? {}) as { malwareScanner?: boolean; dailyBackup?: boolean; docker?: boolean };
62	  const setup: string[] = [];
63	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
64	  if (addons.malwareScanner)
65	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
66	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
67	
68	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
69	  return `#cloud-config
70	package_update: true
71	packages:
72	  - qemu-guest-agent
73	ssh_pwauth: true
74	disable_root: false
75	write_files:
76	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
77	    permissions: "0644"
78	    content: |
79	      PermitRootLogin yes
80	      PasswordAuthentication yes
81	  - path: /root/nxeon-setup.sh
82	    permissions: "0755"
83	    content: |
84	${indentBlock(script, 6)}
85	runcmd:
86	  - systemctl enable --now qemu-guest-agent
87	  - systemctl restart ssh || systemctl restart sshd
88	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
89	`;
90	}
