95	async function provision(job: Job) {
96	  const server = await loadServer(job);
97	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
98	
99	  const { conn, row: nodeRow } = await nodeFor(server);
100	  const storage = server.plan.storageTier === "hdd"
101	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
102	    : nodeRow?.storageNvme ?? "vmdata";
103	
104	  const vmid = server.vmid ?? (await conn.nextVmid());
105	  const password = generatePassword();
106	
107	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
108	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
109	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
110	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
111	  const { getSettingBool: _settingBool } = await import("../lib/settings");
112	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
113	  if (wantDedicated && ovhConfigured()) {
114	    try {
115	      dedicated = await allocateDedicatedIp(server.id, vmid);
116	    } catch (e) {
117	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
118	    }
119	  }
120	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp()));
121	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort()));
122	
123	  await db.server.update({
124	    where: { id: server.id },
125	    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
126	  });
127	
128	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
129	  const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
130	    newid: vmid,
131	    name: server.hostname,
132	    full: 1,
133	    storage,
134	  });
135	  await conn.waitForTask(cloneUpid, 600_000);
136	
137	  // Per-server cloud-init snippet (base + panel/app install + add-ons)
138	  const snippet = buildCloudInit(server);
139	  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
140	    console.error("[worker] snippet write failed", e)
141	  );
142	
143	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
144	  const sshkeys = keys.length
145	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
146	    : undefined;
147	  const cfg: Record<string, any> = {
148	    cores: server.plan.cpuCores,
149	    memory: server.plan.ramMB,
150	    ciuser: "root",
151	    cipassword: password,
152	    sshkeys,
153	    nameserver: "1.1.1.1 8.8.8.8",
154	    onboot: 1,
155	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
156	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
157	  };
158	  if (dedicated) {
159	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
160	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
161	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
162	  } else {
163	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp()}`;
164	  }
165	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
166	
167	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
168	    disk: "scsi0",
169	    size: `${server.plan.diskGB}G`,
170	  });
171	
172	  if (!dedicated) await syncPortForwards();
173	
174	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
175	  await conn.waitForTask(startUpid);
176	
177	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
178	  const isImage = server.osTemplate.category !== "PLAIN_OS";
179	  const sshLine = dedicated
180	    ? `ssh root@${dedicated.address}`
181	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
182	  await notify(
183	    server.userId,
184	    `Server ${server.hostname} is ready`,
185	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
186	    `/dashboard/servers/${server.id}`
187	  );
188	}
