243	async function suspend(job: Job, unsuspend: boolean) {
244	  const server = await loadServer(job);
245	  const { conn } = await nodeFor(server);
246	  if (unsuspend) {
247	    // The dedicated IP was returned to the pool while suspended — re-allocate one
248	    // and reconfigure the public network before starting the VM back up.
249	    if (ovhConfigured() && server.vmid) {
250	      const { getSettingBool: _sb } = await import("../lib/settings");
251	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
252	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
253	      if (wantDedicated && !alreadyHas) {
254	        try {
255	          const d = await allocateDedicatedIp(server.id, server.vmid);
256	          if (d) {
257	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
258	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
259	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
260	            });
261	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
262	          }
263	        } catch (e) {
264	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; keeping current network", e);
265	        }
266	      }
267	    }
268	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
269	    await syncPortForwards();
270	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
271	    await conn.waitForTask(upid);
272	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
273	  } else {
274	    try {
275	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
276	      await conn.waitForTask(upid);
277	    } catch { /* may already be stopped */ }
278	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
279	    await syncPortForwards();
280	    // Return the dedicated IP to the pool while the server is suspended, so it
281	    // can be handed to a paying server. Re-allocated on unsuspend.
282	    if (ovhConfigured()) {
283	      try {
284	        await releaseDedicatedIp(server.id);
285	      } catch (e) {
286	        console.error("[worker] release dedicated IP on suspend failed", e);
287	      }
288	    }
289	  }
290	}
