364	async function passwordReset(job: Job) {
365	  const server = await loadServer(job);
366	  if (!server.vmid) throw new Error("password reset: server has no VM yet");
367	  const { conn } = await nodeFor(server);
368	  const password = generatePassword();
369	
370	  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
371	  let applied = false;
372	  try {
373	    const upid = await conn.post(
374	      `/nodes/${conn.node}/qemu/${server.vmid}/agent/set-user-password`,
375	      { username: "root", password }
376	    );
377	    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
378	    applied = true;
379	  } catch (e) {
380	    console.error("[worker] agent set-user-password failed, falling back to cloud-init", e);
381	  }
382	
383	  // Fallback: rewrite cloud-init password and reboot so it reapplies.
384	  if (!applied) {
385	    await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { cipassword: password });
386	    if (server.status === "RUNNING") {
387	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/reboot`, {});
388	      await conn.waitForTask(upid);
389	    }
390	  }
391	
392	  await db.server.update({ where: { id: server.id }, data: { rootPassword: password } });
393	  await notify(
394	    server.userId,
395	    `Root password reset for ${server.hostname}`,
396	    "Your new root password is available on the server's Overview tab.",
397	    `/dashboard/servers/${server.id}`
398	  );
399	}
