440	async function runJob(job: Job) {
441	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
442	  await db.job.update({
443	    where: { id: job.id },
444	    data: { status: "RUNNING", attempts: { increment: 1 } },
445	  });
446	  try {
447	    await handlers[job.type](job);
448	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
449	    console.log(`[worker] job ${job.id} DONE`);
450	  } catch (e: any) {
451	    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
452	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
453	    const current = await db.job.findUnique({ where: { id: job.id } });
454	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
455	    await db.job.update({
456	      where: { id: job.id },
457	      data: { status: retriable ? "QUEUED" : "FAILED", error },
458	    });
459	    if (!retriable && job.serverId) {
460	      const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
461	      if (stillExists) {
462	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
463	      }
464	    }
465	  }
466	}
