/**
 * Pricing + renewal-period math for the recurring add-on products
 * (business email subscriptions and block-storage volumes).
 *
 * Deliberately PURE: no `db`, no I/O, no side effects — everything here is a
 * plain function over plain values so the renewal policy can be unit-tested
 * without a database. The worker sweep (`worker/product-renewals.ts`) owns all
 * the reads/writes and asks this module *what* should happen.
 *
 * Policy shape mirrors `worker/billing.ts` (VPS/domains) so customers see one
 * consistent billing behaviour across every product:
 *   warn before expiry -> expire -> grace period -> enforce (suspend / detach)
 */

import { addMonths } from "./billing-terms";

export const DAY_MS = 86_400_000;

/** Read a positive integer from the environment, falling back on a default. */
export function envInt(name: string, fallback: number): number {
  const raw = process.env[name];
  const n = Number(raw);
  return raw !== undefined && Number.isFinite(n) && n >= 0 ? n : fallback;
}

/**
 * Days after expiry during which the product keeps working while we retry the
 * charge and nag the customer. Shares NXEON_GRACE_DAYS with worker/billing.ts
 * so every product on the account expires on the same schedule.
 */
export const PRODUCT_GRACE_DAYS = envInt("NXEON_GRACE_DAYS", 3);

/** How many days before expiry we send the "renews soon" heads-up. */
export const PRODUCT_WARN_DAYS = envInt("NXEON_PRODUCT_WARN_DAYS", 3);

/**
 * Days after the grace window before an unpaid, detached volume is considered
 * abandoned and may be reclaimed by staff. Nothing in this codebase deletes
 * customer data automatically — this only drives the wording of the warning so
 * the customer knows the disk will not sit there unpaid forever.
 */
export const PRODUCT_RECLAIM_DAYS = envInt("NXEON_TERMINATE_DAYS", 10);

/** Notification dedupe window (matches the 4-day window used by billing.ts). */
export const NOTIFY_DEDUPE_DAYS = envInt("NXEON_PRODUCT_NOTIFY_DEDUPE_DAYS", 4);

/** Volumes are priced per month and always renew monthly. */
export const VOLUME_TERM_MONTHS = 1;

/** "$12.34" — the money format used across notifications and wallet lines. */
export function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

/** Date as "YYYY-MM-DD" for human-readable deadlines in notifications. */
export function ymd(d: Date): string {
  return d.toISOString().slice(0, 10);
}

/** Amount charged to renew an email subscription for one plan term. */
export function emailRenewalCents(plan: { priceCents: number }): number {
  return Math.max(0, Math.round(plan.priceCents));
}

/** Plan term in whole months, clamped to >= 1 so a bad row can't stall renewal. */
export function emailRenewalMonths(plan: { termMonths?: number | null }): number {
  const m = Math.round(Number(plan.termMonths ?? 1));
  return Number.isFinite(m) && m >= 1 ? m : 1;
}

/** Amount charged to renew a volume for one month. */
export function volumeRenewalCents(volume: { priceCents: number }): number {
  return Math.max(0, Math.round(volume.priceCents));
}

/**
 * The expiry a renewal should advance to.
 *
 * The base is `max(currentExpiry, now)`, so an item that has been expired for
 * months is brought forward to one full term from *today* with a single charge
 * rather than being back-billed for every missed period. This also guarantees
 * the new expiry is always strictly in the future, which is what makes the
 * sweep idempotent (the "due" query only selects `expiresAt < now`).
 */
export function nextExpiry(
  currentExpiry: Date | null | undefined,
  now: Date,
  months: number
): Date {
  const base = new Date(
    Math.max(currentExpiry ? currentExpiry.getTime() : now.getTime(), now.getTime())
  );
  return addMonths(base, Math.max(1, Math.round(months)));
}

/** Instant the grace period ends for an item that expired at `expiresAt`. */
export function graceEndsAt(expiresAt: Date, graceDays: number = PRODUCT_GRACE_DAYS): Date {
  return new Date(expiresAt.getTime() + graceDays * DAY_MS);
}

/** True once the grace period after `expiresAt` has fully elapsed. */
export function isPastGrace(
  expiresAt: Date,
  now: Date,
  graceDays: number = PRODUCT_GRACE_DAYS
): boolean {
  return now.getTime() > graceEndsAt(expiresAt, graceDays).getTime();
}

/** Date after which an unpaid volume may be reclaimed (messaging only). */
export function reclaimAt(
  expiresAt: Date,
  graceDays: number = PRODUCT_GRACE_DAYS,
  reclaimDays: number = PRODUCT_RECLAIM_DAYS
): Date {
  return new Date(expiresAt.getTime() + (graceDays + reclaimDays) * DAY_MS);
}

/** Lower bound for "have we already sent this notification recently?" lookups. */
export function dedupeSince(now: Date, days: number = NOTIFY_DEDUPE_DAYS): Date {
  return new Date(now.getTime() - days * DAY_MS);
}

/** True when the item has passed its paid-through date and owes a renewal. */
export function isDueForRenewal(expiresAt: Date | null | undefined, now: Date): boolean {
  return !!expiresAt && expiresAt.getTime() < now.getTime();
}

/** True when the item expires inside the pre-expiry warning window. */
export function isRenewingSoon(
  expiresAt: Date | null | undefined,
  now: Date,
  warnDays: number = PRODUCT_WARN_DAYS
): boolean {
  if (!expiresAt) return false;
  const t = expiresAt.getTime();
  return t > now.getTime() && t < now.getTime() + warnDays * DAY_MS;
}

/** Whether the wallet covers a renewal (free items always "afford" themselves). */
export function canAfford(balanceCents: number, priceCents: number): boolean {
  return priceCents <= 0 || balanceCents >= priceCents;
}

/**
 * What the sweep should do with an item that is past its expiry date.
 *  - `renew`   charge the wallet and push `expiresAt` forward
 *  - `grace`   still inside the grace window: leave it running, nag the owner
 *  - `enforce` grace elapsed and unpaid: suspend (email) / detach (volume)
 */
export type RenewalAction = "renew" | "grace" | "enforce";

export function renewalDecision(opts: {
  expiresAt: Date;
  now: Date;
  autoRenew: boolean;
  balanceCents: number;
  priceCents: number;
  graceDays?: number;
}): RenewalAction {
  const { expiresAt, now, autoRenew, balanceCents, priceCents } = opts;
  if (autoRenew && canAfford(balanceCents, priceCents)) return "renew";
  if (isPastGrace(expiresAt, now, opts.graceDays)) return "enforce";
  return "grace";
}

/**
 * Whether a pre-expiry warning is warranted: only bother the customer when the
 * renewal would actually fail today (auto-renew off, or wallet too low).
 */
export function needsUpcomingWarning(opts: {
  autoRenew: boolean;
  balanceCents: number;
  priceCents: number;
}): boolean {
  return !(opts.autoRenew && canAfford(opts.balanceCents, opts.priceCents));
}

import { db } from "../lib/db";
import { debitWallet, InsufficientBalanceError } from "../lib/wallet";
import {
  PRODUCT_GRACE_DAYS,
  PRODUCT_WARN_DAYS,
  VOLUME_TERM_MONTHS,
  canAfford,
  dedupeSince,
  emailRenewalCents,
  emailRenewalMonths,
  graceEndsAt,
  money,
  needsUpcomingWarning,
  nextExpiry,
  reclaimAt,
  renewalDecision,
  volumeRenewalCents,
  ymd,
} from "../lib/product-billing";

/**
 * Recurring billing for the add-on products: business email subscriptions and
 * block-storage volumes. Until this existed only the *first* period was charged
 * at order time and nothing ever renewed — every one of these products was
 * silently free after month one.
 *
 * Policy (mirrors worker/billing.ts so the whole account behaves the same):
 *   T-3d   warn the owner if the renewal would fail (no funds / auto-renew off)
 *   T+0    charge the wallet, push `expiresAt` forward one term
 *   T+0..G still unpaid: keep it running, nag once per dedupe window
 *   T+G    enforce — email: status SUSPENDED (mailboxes kept)
 *                    volume: DETACHED + VOLUME_DETACH job (data kept)
 * Nothing here ever deletes customer data.
 *
 * The orchestrator (worker/index.ts) calls `productRenewalSweep()` on a timer.
 * Every step is individually try/caught so one poisoned row can never abort the
 * sweep, and every mutation is a conditional compare-and-swap so a re-run — or
 * two workers racing — can never double-charge.
 */

const LOG = "[product-billing]";

/** Thrown inside a renewal transaction when another sweep already handled the row. */
class AlreadyHandledError extends Error {
  constructor(what: string) {
    super(`already handled: ${what}`);
    this.name = "AlreadyHandledError";
  }
}

/** Run a sweep phase, swallowing (but logging) any failure so the rest proceeds. */
async function phase(name: string, fn: () => Promise<void>): Promise<void> {
  try {
    await fn();
  } catch (e) {
    console.error(`${LOG} phase "${name}" failed`, e);
  }
}

/** Run a per-row step; a bad row is logged and skipped, never fatal. */
async function step(what: string, fn: () => Promise<void>): Promise<void> {
  try {
    await fn();
  } catch (e) {
    console.error(`${LOG} ${what} failed`, e);
  }
}

/** Best-effort notification (a notify failure must never roll back a charge). */
async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error(`${LOG} notify failed`, e);
  }
}

/**
 * Send a notification at most once per dedupe window, keyed on the entity label
 * plus a stable marker phrase in the title (same technique as worker/billing.ts).
 */
async function notifyOnce(
  now: Date,
  userId: string,
  label: string,
  marker: string,
  title: string,
  body: string,
  href: string
) {
  const already = await db.notification.findFirst({
    where: {
      userId,
      createdAt: { gt: dedupeSince(now) },
      AND: [{ title: { contains: label } }, { title: { contains: marker } }],
    },
    select: { id: true },
  });
  if (already) return;
  await notify(userId, title, body, href);
}

// ---------------------------------------------------------------------------
// Business email subscriptions
// ---------------------------------------------------------------------------

const EMAIL_HREF = "/dashboard/email";

/** Heads-up for subscriptions expiring soon whose renewal would fail today. */
async function emailUpcomingWarnings(now: Date) {
  const soon = new Date(now.getTime() + PRODUCT_WARN_DAYS * 86400_000);
  const upcoming = await db.emailSubscription.findMany({
    where: { status: "ACTIVE", expiresAt: { gt: now, lt: soon } },
    include: { emailPlan: true, user: true },
  });

  for (const sub of upcoming) {
    await step(`email warn ${sub.id}`, async () => {
      const priceCents = emailRenewalCents(sub.emailPlan);
      if (!needsUpcomingWarning({ autoRenew: sub.autoRenew, balanceCents: sub.user.balanceCents, priceCents })) {
        return;
      }
      await notifyOnce(
        now,
        sub.userId,
        sub.domainName,
        "email renews soon",
        `${sub.domainName} email renews soon — action needed`,
        sub.autoRenew
          ? `Renewal is ${money(priceCents)} but your balance is ${money(sub.user.balanceCents)}. Top up before ${ymd(sub.expiresAt!)} to keep your mailboxes delivering.`
          : `Auto-renew is off. Renew manually before ${ymd(sub.expiresAt!)} to avoid suspension.`,
        EMAIL_HREF
      );
    });
  }
}

/**
 * Charge + extend one subscription atomically.
 *
 * The compare-and-swap on `expiresAt` is the double-charge guard: the update
 * only matches while the row still carries the *old* expiry we based the
 * decision on, so a concurrent (or repeated) sweep matches zero rows, throws,
 * and rolls the whole transaction — wallet debit included — back.
 * Returns true when this call is the one that actually renewed.
 */
async function chargeEmailRenewal(
  sub: { id: string; userId: string; domainName: string; expiresAt: Date | null },
  planName: string,
  priceCents: number,
  newExpiry: Date
): Promise<boolean> {
  try {
    await db.$transaction(async (tx) => {
      const advanced = await tx.emailSubscription.updateMany({
        where: { id: sub.id, status: "ACTIVE", expiresAt: sub.expiresAt },
        data: { expiresAt: newExpiry },
      });
      if (advanced.count === 0) throw new AlreadyHandledError(`email ${sub.id}`);

      if (priceCents > 0) {
        await debitWallet(tx, sub.userId, priceCents);
        await tx.walletTransaction.create({
          data: {
            userId: sub.userId,
            amountCents: -priceCents,
            description: `Business Email renewal: ${planName} for ${sub.domainName}`,
          },
        });
      }
      await tx.auditLog.create({
        data: {
          userId: sub.userId,
          action: "billing.renewed",
          detail: `email ${sub.id} ${sub.domainName} ${money(priceCents)} -> ${ymd(newExpiry)}`,
        },
      });
    });
    return true;
  } catch (e) {
    if (e instanceof AlreadyHandledError) {
      console.log(`${LOG} email ${sub.id} already renewed by another pass — skipping`);
      return false;
    }
    if (e instanceof InsufficientBalanceError) {
      // Balance was spent between the read and the debit; the warn/grace path
      // picks it up on the next sweep.
      console.log(`${LOG} email ${sub.id} lost the race for funds — retrying next sweep`);
      return false;
    }
    throw e;
  }
}

/** Suspend an unpaid subscription past grace. Mailboxes are never deleted. */
async function suspendEmail(
  sub: { id: string; userId: string; domainName: string; expiresAt: Date | null },
  priceCents: number
) {
  const suspended = await db.emailSubscription.updateMany({
    where: { id: sub.id, status: "ACTIVE" },
    data: { status: "SUSPENDED" },
  });
  if (suspended.count === 0) return; // another pass got there first

  await db.auditLog.create({
    data: {
      userId: sub.userId,
      action: "billing.suspended_unpaid",
      detail: `email ${sub.id} ${sub.domainName}`,
    },
  });
  await notify(
    sub.userId,
    `${sub.domainName} email suspended — payment overdue`,
    `Mail delivery is paused. Your mailboxes and their contents are kept — top up ${money(priceCents)} and renew from your email page to restore delivery.`,
    EMAIL_HREF
  );
  console.log(`${LOG} suspended unpaid email subscription ${sub.id} (${sub.domainName})`);
}

/** Renew / warn / suspend every ACTIVE subscription that is past its expiry. */
async function emailDueSweep(now: Date) {
  const due = await db.emailSubscription.findMany({
    where: { status: "ACTIVE", expiresAt: { not: null, lt: now } },
    include: { emailPlan: true, user: true },
  });

  for (const sub of due) {
    await step(`email renewal ${sub.id}`, async () => {
      if (!sub.expiresAt) return;
      const priceCents = emailRenewalCents(sub.emailPlan);
      const action = renewalDecision({
        expiresAt: sub.expiresAt,
        now,
        autoRenew: sub.autoRenew,
        balanceCents: sub.user.balanceCents,
        priceCents,
      });

      if (action === "renew") {
        const newExpiry = nextExpiry(sub.expiresAt, now, emailRenewalMonths(sub.emailPlan));
        const renewed = await chargeEmailRenewal(sub, sub.emailPlan.name, priceCents, newExpiry);
        if (!renewed) return;
        await notify(
          sub.userId,
          `${sub.domainName} email renewed`,
          `Charged ${money(priceCents)} for ${sub.emailPlan.name}. Next renewal ${ymd(newExpiry)}.`,
          EMAIL_HREF
        );
        console.log(`${LOG} renewed email ${sub.domainName} until ${newExpiry.toISOString()}`);
        return;
      }

      if (action === "enforce") {
        await suspendEmail(sub, priceCents);
        return;
      }

      // Still inside the grace window — keep it delivering, nag once.
      await notifyOnce(
        now,
        sub.userId,
        sub.domainName,
        "email renewal failed",
        `${sub.domainName} email renewal failed — top up to keep it active`,
        sub.autoRenew
          ? `We couldn't charge ${money(priceCents)} (balance ${money(sub.user.balanceCents)}). Mail keeps flowing until ${ymd(graceEndsAt(sub.expiresAt, PRODUCT_GRACE_DAYS))}, then the subscription is suspended. Your mailboxes are not deleted.`
          : `Auto-renew is off and this subscription expired. Renew before ${ymd(graceEndsAt(sub.expiresAt, PRODUCT_GRACE_DAYS))} to avoid suspension. Your mailboxes are not deleted.`,
        EMAIL_HREF
      );
    });
  }
}

// ---------------------------------------------------------------------------
// Block storage volumes
// ---------------------------------------------------------------------------

const VOLUME_HREF = "/dashboard/volumes";

/** Volume states that are live and therefore billable. */
const BILLABLE_VOLUME_STATUSES = ["PENDING", "ATTACHED", "DETACHED"];

/** Heads-up for volumes expiring soon that the wallet can't cover. */
async function volumeUpcomingWarnings(now: Date) {
  const soon = new Date(now.getTime() + PRODUCT_WARN_DAYS * 86400_000);
  const upcoming = await db.volume.findMany({
    where: { status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: { gt: now, lt: soon } },
    include: { user: true },
  });

  for (const volume of upcoming) {
    await step(`volume warn ${volume.id}`, async () => {
      const priceCents = volumeRenewalCents(volume);
      if (canAfford(volume.user.balanceCents, priceCents)) return;
      await notifyOnce(
        now,
        volume.userId,
        volume.name,
        "volume renews soon",
        `Volume "${volume.name}" renews soon — action needed`,
        `Renewal is ${money(priceCents)}/mo but your balance is ${money(volume.user.balanceCents)}. Top up before ${ymd(volume.expiresAt!)} — an unpaid volume is detached from its server (your data is kept).`,
        VOLUME_HREF
      );
    });
  }
}

/**
 * Charge + extend one volume atomically. Same compare-and-swap on `expiresAt`
 * as the email path, so re-running the sweep can never bill a second month.
 */
async function chargeVolumeRenewal(
  volume: { id: string; userId: string; name: string; sizeGB: number; expiresAt: Date | null; status: string },
  priceCents: number,
  newExpiry: Date
): Promise<boolean> {
  try {
    await db.$transaction(async (tx) => {
      const advanced = await tx.volume.updateMany({
        where: { id: volume.id, status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: volume.expiresAt },
        data: { expiresAt: newExpiry },
      });
      if (advanced.count === 0) throw new AlreadyHandledError(`volume ${volume.id}`);

      if (priceCents > 0) {
        await debitWallet(tx, volume.userId, priceCents);
        await tx.walletTransaction.create({
          data: {
            userId: volume.userId,
            amountCents: -priceCents,
            description: `Block storage renewal: ${volume.name} (${volume.sizeGB} GB)`,
          },
        });
      }
      await tx.auditLog.create({
        data: {
          userId: volume.userId,
          action: "billing.renewed",
          detail: `volume ${volume.id} ${volume.name} ${money(priceCents)} -> ${ymd(newExpiry)}`,
        },
      });
    });
    return true;
  } catch (e) {
    if (e instanceof AlreadyHandledError) {
      console.log(`${LOG} volume ${volume.id} already renewed by another pass — skipping`);
      return false;
    }
    if (e instanceof InsufficientBalanceError) {
      console.log(`${LOG} volume ${volume.id} lost the race for funds — retrying next sweep`);
      return false;
    }
    throw e;
  }
}

/**
 * Enforcement for an unpaid volume past grace: detach only, never destroy.
 * An ATTACHED volume is flipped to DETACHED and a VOLUME_DETACH job is queued
 * (both in one transaction, so we never mark it detached without doing it).
 * The underlying disk — and every byte on it — is left intact.
 */
async function detachUnpaidVolume(
  volume: {
    id: string;
    userId: string;
    name: string;
    serverId: string | null;
    status: string;
    expiresAt: Date | null;
  },
  priceCents: number,
  now: Date
) {
  if (volume.status !== "ATTACHED") {
    // Nothing to detach (PENDING / already DETACHED) — just keep nagging.
    await notifyOnce(
      now,
      volume.userId,
      volume.name,
      "volume unpaid",
      `Volume "${volume.name}" is unpaid`,
      `This volume is overdue by ${money(priceCents)}/mo. Your data is retained, but the volume may be removed if it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))}. Top up to keep it.`,
      VOLUME_HREF
    );
    return;
  }

  // Respect the one-in-flight-job guard so we don't collide with a user or
  // worker operation already running on that server; retry on the next sweep.
  if (volume.serverId) {
    const busy = await db.job.count({
      where: { serverId: volume.serverId, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (busy > 0) return;
  }

  try {
    await db.$transaction(async (tx) => {
      const flipped = await tx.volume.updateMany({
        where: { id: volume.id, status: "ATTACHED" },
        data: { status: "DETACHED" },
      });
      if (flipped.count === 0) throw new AlreadyHandledError(`volume ${volume.id}`);
      await tx.job.create({
        data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId: volume.id } },
      });
      await tx.auditLog.create({
        data: {
          userId: volume.userId,
          action: "billing.volume_detached_unpaid",
          detail: `volume ${volume.id} ${volume.name}`,
        },
      });
    });
  } catch (e) {
    if (e instanceof AlreadyHandledError) return;
    throw e;
  }

  await notify(
    volume.userId,
    `Volume "${volume.name}" detached — payment overdue`,
    `We couldn't collect ${money(priceCents)} for this volume, so it was detached from your server. Nothing was deleted: all data on the volume is retained and re-attaches exactly as it was once you top up and renew. If it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))} the volume may be removed.`,
    VOLUME_HREF
  );
  console.log(`${LOG} detached unpaid volume ${volume.id} (${volume.name})`);
}

/** Renew / warn / detach every billable volume that is past its expiry. */
async function volumeDueSweep(now: Date) {
  const due = await db.volume.findMany({
    where: { status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: { not: null, lt: now } },
    include: { user: true },
  });

  for (const volume of due) {
    await step(`volume renewal ${volume.id}`, async () => {
      if (!volume.expiresAt) return;
      const priceCents = volumeRenewalCents(volume);
      const action = renewalDecision({
        expiresAt: volume.expiresAt,
        now,
        autoRenew: true, // volumes have no opt-out; they renew until deleted
        balanceCents: volume.user.balanceCents,
        priceCents,
      });

      if (action === "renew") {
        const newExpiry = nextExpiry(volume.expiresAt, now, VOLUME_TERM_MONTHS);
        const renewed = await chargeVolumeRenewal(volume, priceCents, newExpiry);
        if (!renewed) return;
        await notify(
          volume.userId,
          `Volume "${volume.name}" renewed`,
          `Charged ${money(priceCents)} for ${volume.sizeGB} GB. Next renewal ${ymd(newExpiry)}.`,
          VOLUME_HREF
        );
        console.log(`${LOG} renewed volume ${volume.id} until ${newExpiry.toISOString()}`);
        return;
      }

      if (action === "enforce") {
        await detachUnpaidVolume(volume, priceCents, now);
        return;
      }

      // Inside grace — the volume stays attached and usable; nag once.
      await notifyOnce(
        now,
        volume.userId,
        volume.name,
        "volume renewal failed",
        `Volume "${volume.name}" renewal failed — top up to keep it attached`,
        `We couldn't charge ${money(priceCents)} (balance ${money(volume.user.balanceCents)}). The volume stays attached until ${ymd(graceEndsAt(volume.expiresAt, PRODUCT_GRACE_DAYS))}, then it is detached from your server. Your data is never deleted automatically.`,
        VOLUME_HREF
      );
    });
  }
}

// ---------------------------------------------------------------------------

/**
 * Renewal sweep for the add-on products. Safe to call as often as you like:
 * each phase only acts on rows whose `expiresAt` is genuinely in the past, and
 * every charge advances `expiresAt` in the same transaction, so repeated runs
 * are no-ops rather than repeat charges.
 *
 * Wire into the worker loop next to `billingSweep()` (see worker/index.ts).
 */
export async function productRenewalSweep(): Promise<void> {
  const now = new Date();
  await phase("email upcoming warnings", () => emailUpcomingWarnings(now));
  await phase("email renewals", () => emailDueSweep(now));
  await phase("volume upcoming warnings", () => volumeUpcomingWarnings(now));
  await phase("volume renewals", () => volumeDueSweep(now));
}

